import sqlite3
import requests
import time
from concurrent.futures import ThreadPoolExecutor, as_completed
import argparse

def fetch_user_name(id):
    url = f"https://api.example.com/v1/users/{id}"
    try:
        response = requests.get(url, timeout=5)
        response.raise_for_status()
        data = response.json()
        return data.get("name", "N/A")
    except (requests.RequestException, ValueError):
        return "N/A"

def process_ids(ids):
    results = []
    with ThreadPoolExecutor(max_workers=10) as executor:
        futures = {executor.submit(fetch_user_name, id): id for id in ids}
        for future in as_completed(futures, timeout=1):
            try:
                name = future.result()
                results.append((futures[future], name))
            except Exception:
                results.append((futures[future], "N/A"))
    return results

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("query", help="SQL query to execute on app.db")
    args = parser.parse_args()

    conn = sqlite3.connect("app.db")
    cursor = conn.cursor()
    cursor.execute(args.query)
    ids = [row[0] for row in cursor.fetchall()]
    conn.close()

    results = process_ids(ids)
    for id, name in results:
        print(f"{id}: {name}")

if __name__ == "__main__":
    main()
